package controllers

import (
	"log"
	"net/http"
	"os"
	"uranus/internal/wsterminal"

	"github.com/gin-gonic/gin"
	"github.com/gorilla/websocket"
)

// WebSocket upgrader configuration. CheckOrigin is left to gorilla's default:
// the page opening the socket must come from the same host as the request. The
// terminal is a root shell authenticated by the session cookie, so other sites
// (even ones served from the same server) must not be able to open it.
// Behind a reverse proxy, the proxy has to forward the Host header (the site
// templates generated by uranus do).
var wsUpgrader = websocket.Upgrader{
	ReadBufferSize:  4096,
	WriteBufferSize: 4096,
}

// WebSocketTerminalHandler opens a shell on this server for the terminal page.
func WebSocketTerminalHandler(c *gin.Context) {
	log.Printf("[WS Terminal] Upgrading connection to WebSocket...")

	// Upgrade HTTP connection to WebSocket
	conn, err := wsUpgrader.Upgrade(c.Writer, c.Request, nil)
	if err != nil {
		// Upgrade has already answered with an HTTP error status
		log.Printf("[WS Terminal] Failed to upgrade connection: %v", err)
		return
	}

	log.Printf("[WS Terminal] WebSocket connection established, getting terminal manager...")

	// Get global terminal manager
	manager := wsterminal.GetGlobalManager()
	if manager == nil {
		log.Printf("[WS Terminal] Error: Terminal manager is nil")
		conn.WriteMessage(websocket.TextMessage, []byte("Internal error: Terminal manager not initialized"))
		conn.Close()
		return
	}

	log.Printf("[WS Terminal] Creating terminal session...")

	// Create terminal session
	terminal, err := manager.CreateTerminal(conn, "")
	if err != nil {
		log.Printf("[WS Terminal] Failed to create terminal: %v", err)
		conn.WriteMessage(websocket.TextMessage, []byte("Failed to create terminal: "+err.Error()))
		conn.Close()
		return
	}

	log.Printf("[WS Terminal] Terminal created successfully, starting I/O...")

	// Start terminal I/O
	terminal.Start()

	log.Printf("[WS Terminal] Terminal I/O started")
}

// TerminalPageHandler serves the terminal page, titled with the server's name
// until the shell sets its own title.
func TerminalPageHandler(c *gin.Context) {
	name, _ := os.Hostname()
	c.HTML(http.StatusOK, "terminal.html", gin.H{"hostname": name})
}
